import{_ as e,o as t,c as i,a7 as n}from"./chunks/framework.xMNG87v2.js";const l="/website/previews/7e5d5fa3888b/img/windows-firewall.png",w=JSON.parse('{"title":"Opening ports in your firewall","description":"Opening UDP ports 19132 (IPv4) and 19133 (IPv6) in Windows Firewall or ufw so that players can connect to your server. It is not required if you are not using a firewall at all.","frontmatter":{"title":"Opening ports in your firewall","outline":"deep","description":"Opening UDP ports 19132 (IPv4) and 19133 (IPv6) in Windows Firewall or ufw so that players can connect to your server. It is not required if you are not using a firewall at all.","head":[["link",{"rel":"canonical","href":"https://axolotl-pm.org/docs/connecting/configure-firewall"}]]},"headers":[],"relativePath":"docs/connecting/configure-firewall.md","filePath":"docs/connecting/configure-firewall.md","lastUpdated":1790689997000}'),a={name:"docs/connecting/configure-firewall.md"};function r(s,o,c,u,d,p){return t(),i("div",null,[...o[0]||(o[0]=[n('<h1 id="opening-ports-in-your-firewall" tabindex="-1">Opening ports in your firewall <a class="header-anchor" href="#opening-ports-in-your-firewall" aria-label="Permalink to &quot;Opening ports in your firewall&quot;">​</a></h1><p>If you have a firewall set up, you need to allow access to UDP port <code>19132</code> (for IPv4) and/or <code>19133</code> (for IPv6).</p><h2 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Note</p><p>You’ll probably need the admin for your computer to make changes to the firewall settings.</p></div><p>Usually, on first server startup on Windows, a dialog like this will pop up.</p><p>Click “Allow access” to allow Axolotl-PM through the firewall and allow players to connect.</p><blockquote><p><img src="'+l+'" alt=""></p></blockquote><p>If you didn’t get the dialog or you clicked “Cancel”, you can do the following instead:</p><ul><li>Search for “firewall” in the Start Menu and select “Allow an app through Windows Firewall”.</li><li>Click “Change settings” in the top right (you might be asked for an admin login).</li><li>Scroll down the list until you find “php.exe”.</li><li>If you’re on a private network (typical for a home WiFi or LAN), tick the “private” box.</li><li>If you’re on a public network, you can tick the “public” box, but be aware that other people might be able to join your server on untrusted networks (e.g. if you’re connected to public WiFi).</li><li>Click “OK” at the bottom when you’re done.</li></ul><h2 id="ubuntu-or-other-linux-distros-with-ufw" tabindex="-1">Ubuntu (or other Linux distros with <code>ufw</code>) <a class="header-anchor" href="#ubuntu-or-other-linux-distros-with-ufw" aria-label="Permalink to &quot;Ubuntu (or other Linux distros with `ufw`)&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Note</p><p>You’ll need <code>sudo</code> for this.</p></div><p>There are many different flavours of Linux, and we can’t cover them all here. However, you’ll usually find <code>ufw</code> on Linux machines.</p><p>First, check if <code>ufw</code> is enabled by running <code>sudo ufw status</code>. If it says “Status: inactive”, you don’t need to do anything else.</p><p>If it’s <em>active</em>, do <code>sudo ufw allow 19132/udp</code> (for IPv4) or <code>sudo ufw allow 19133/udp</code> (for IPv6).</p>',14)])])}const h=e(a,[["render",r]]);export{w as __pageData,h as default};
